<template><section><h2 class="text-2xl font-bold">{{pendingOnly?'Đơn hàng chờ hoàn tất':'Tất cả đơn hàng'}}</h2><p v-if="error" class="mt-4 text-error">{{error}}</p><p v-else-if="loading" class="mt-4 text-gray-400">Đang tải…</p><Table v-else :columns="columns" :data="visible" class="mt-5"><template #status="{row}"><span :class="row.status==='CONFIRMED'?'text-primary':'text-gray-300'">{{row.status}}</span></template><template #actions="{row}"><router-link class="mr-3 text-gray-300 hover:text-white" :to="{name:'admin-order-detail',params:{id:row.orderId}}">Xem</router-link><button v-if="row.status==='CONFIRMED'" class="text-primary" @click="complete(row)">Hoàn tất</button></template></Table></section></template><script setup>import{computed,onMounted,ref}from'vue';import Table from'../../components/ui/Table.vue';import{adminApi}from'../../api/adminService';const props=defineProps({pendingOnly:Boolean});const orders=ref([]),loading=ref(true),error=ref('');const columns=[{key:'orderId',label:'Order ID'},{key:'farmName',label:'Farm'},{key:'retailerName',label:'Retailer'},{key:'totalAmount',label:'Tổng tiền'},{key:'status',label:'Trạng thái'},{key:'actions',label:''}];const visible=computed(()=>props.pendingOnly?orders.value.filter(o=>o.status==='CONFIRMED'):orders.value);const load=async()=>{loading.value=true;try{orders.value=(await adminApi.orders()).data}catch(e){error.value=e.response?.data?.message||'Không thể tải đơn hàng.'}finally{loading.value=false}};const complete=async(order)=>{if(!window.confirm(`Xác nhận hoàn tất đơn hàng #${order.orderId}?`))return;try{await adminApi.completeOrder(order.orderId);await load()}catch(e){error.value=e.response?.data?.message||'Không thể hoàn tất đơn hàng.'}};onMounted(load)</script>
